﻿'use client';
import { useEffect, useState } from 'react';
import { useUsers } from '@/hooks/useUsers';
import { User } from '@/types';
import Link from 'next/link';

export default function UsersPage() {
  const { getUsers, deleteUser, assignRole } = useUsers();
  const [users, setUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchUsers = async () => {
    const data = await getUsers();
    setUsers(data);
    setLoading(false);
  };

  useEffect(() => {
    fetchUsers();
  }, []);

  const handleDelete = async (id: number, name: string) => {
    if (confirm(`Delete ${name}?`)) {
      await deleteUser(id);
      await fetchUsers();
      const token = localStorage.getItem('access_token');
      if (token) {
        const payload = JSON.parse(atob(token.split('.')[1]));
        await fetch('/api/notify', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ userId: payload.id, message: `${name} was deleted` }),
        });
      }
    }
  };

  const handleRoleChange = async (id: number, newRole: string, name: string) => {
    await assignRole(id, newRole);
    await fetchUsers();
    const token = localStorage.getItem('access_token');
    if (token) {
      const payload = JSON.parse(atob(token.split('.')[1]));
      await fetch('/api/notify', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ userId: payload.id, message: `${name}'s role changed to ${newRole}` }),
      });
    }
  };

  if (loading) return <div className="text-center py-10">Loading users...</div>;

  return (
    <div className="bg-white rounded-2xl shadow-xl p-6">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold text-amber-800">All Users</h1>
        <Link href="/users/create" className="bg-amber-700 text-white px-4 py-2 rounded-lg hover:bg-amber-800">+ Create User</Link>
      </div>
      <div className="overflow-x-auto">
        <table className="w-full text-left">
          <thead className="bg-amber-100">
            <tr><th className="p-3">Name</th><th>Email</th><th>Role</th><th>NID</th><th>Actions</th></tr>
          </thead>
          <tbody>
            {users.map(user => (
              <tr key={user.id} className="border-b hover:bg-amber-50">
                <td className="p-3">{user.name}</td>
                <td>{user.email}</td>
                <td>
                  <select value={user.role} onChange={(e) => handleRoleChange(user.id, e.target.value, user.name)} className="border rounded p-1">
                    <option value="admin">admin</option><option value="manager">manager</option>
                    <option value="receptionist">receptionist</option><option value="customer">customer</option>
                  </select>
                </td>
                <td>{user.nidNumber}</td>
                <td className="space-x-2">
                  <Link href={`/users/${user.id}`} className="text-blue-600 hover:underline">View</Link>
                  <Link href={`/users/${user.id}/edit`} className="text-green-600 hover:underline">Edit</Link>
                  <button onClick={() => handleDelete(user.id, user.name)} className="text-red-600 hover:underline">Delete</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

﻿'use client';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { registerSchema, RegisterInput } from '@/schemas/userSchemas';
import { useUsers } from '@/hooks/useUsers';
import { useRouter } from 'next/navigation';
import { AxiosError } from 'axios';

export default function CreateUserPage() {
  const { createUser } = useUsers();
  const router = useRouter();
  const { register, handleSubmit, formState: { errors } } = useForm<RegisterInput>({
    resolver: zodResolver(registerSchema) as any,
    defaultValues: { role: 'customer', nidNumber: '1234567890123' },
  });

  const onSubmit = async (data: RegisterInput) => {
    try {
      await createUser(data);
      const token = localStorage.getItem('access_token');
      if (token) {
        const payload = JSON.parse(atob(token.split('.')[1]));
        await fetch('/api/notify', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ userId: payload.id, message: 'New user created' }),
        });
      }
      router.push('/users');
    } catch (error) {
      if (error instanceof AxiosError && error.response?.status === 409) {
        alert(error.response.data?.message || 'User already exists');
        return;
      }
      throw error;
    }
  };

  return (
    <div className="max-w-lg mx-auto bg-white rounded-2xl shadow-xl p-8">
      <h1 className="text-2xl font-bold mb-6">Create User</h1>
      <form onSubmit={handleSubmit(onSubmit)} className="space-y-4">
        <input {...register('name')} placeholder="Name" className="w-full border p-3 rounded" />
        {errors.name && <p className="text-red-500">{errors.name.message}</p>}
        <input {...register('email')} placeholder="Email" className="w-full border p-3 rounded" />
        {errors.email && <p className="text-red-500">{errors.email.message}</p>}
        <input {...register('password')} type="password" placeholder="Password" className="w-full border p-3 rounded" />
        {errors.password && <p className="text-red-500">{errors.password.message}</p>}
        <select {...register('role')} className="w-full border p-3 rounded">
          <option value="admin">admin</option><option value="manager">manager</option>
          <option value="receptionist">receptionist</option><option value="customer">customer</option>
        </select>
        <input {...register('nidNumber')} placeholder="NID Number" className="w-full border p-3 rounded" />
        {errors.nidNumber && <p className="text-red-500">{errors.nidNumber.message}</p>}
        <button type="submit" className="bg-amber-700 text-white px-4 py-2 rounded">Create</button>
      </form>
    </div>
  );
}

